def sauts(reseau, depart):
    dist = {depart: 0}
    file = [depart]
    while file:
        r = file.pop(0)
        for v in reseau[r]:
            if v not in dist:
                dist[v] = dist[r] + 1
                file.append(v)
    return dist
```

